"""Rebuild the portable delivery-plan HTML from the reviewed plan.json."""
import json
from html import escape as e
from pathlib import Path

root = Path(__file__).parent
p = json.loads((root / 'plan.json').read_text())
def para(s): return '<p>' + e(s) + '</p>'
def table(headers, rows):
    return '<div class="table-wrap" tabindex="0"><table><thead><tr>' + ''.join('<th scope="col">'+e(h)+'</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+e(str(c))+'</td>' for c in r)+'</tr>' for r in rows) + '</tbody></table></div>'
def section(id, title, body): return f'<section id="{id}"><h2>{e(title)}</h2>{body}</section>'
parts=[]
parts.append(section('definition','1. Product definition', ''.join('<article><h3>'+e(x['title'])+'</h3>'+para(x['body'])+'</article>' for x in p['prd'])))
parts.append(section('requirements','What the product must do',table(['ID','Requirement','Acceptance'],p['requirements'])))
parts.append(section('credits','How credits should work',para('Proposed product rules. Complimentary pilot credits and future purchased credits are distinct from the provider-dollar ledger. The prototype amounts are illustrative.')+table(['Moment','Rule'],p['economics'])))
parts.append(section('journey','2. End-to-end experience',table(['Step','Learner action','What they see','System and credits','Failure path'],p['journey'])))
parts.append(section('design','Design direction', '''<div class="callout"><h3>One clear action at each step</h3><p>Keep the existing Goal → Experience → Context → Review sequence. Add an understandable cost-and-access confirmation instead of provider setup. Use familiar course cards and private reader views. Put detailed usage in Account; show the current maximum and saved work where the learner makes a decision.</p></div><div class="cards"><article><h3>Navigation and hierarchy</h3><p>Your Courses, Create course, and Account &amp; credits remain the primary destinations. Quote confirmation, review and recovery each have one primary action. Model IDs, tokens, policy hashes and operator controls stay outside the learner flow.</p></article><article><h3>Components and copy</h3><p>Use the current app's calm typography, rounded cards and semantic status colors. Label statuses with words and icons. Use “Available”, “Held for this course” and “Used”; explain holds next to the value. Error copy says what happened, what is retained and the next safe action.</p></article><article><h3>Responsive and accessible</h3><p>Single-column mobile layout; no hidden financial totals. Minimum 44px controls, visible focus, semantic headings, associated labels and polite status announcements. Restore focus to the changed heading or error. Support keyboard, screen readers, reduced motion and 200% text.</p></article></div><p><a class="button" href="prototype.html">Open the interactive experience prototype</a> <span class="muted">Synthetic data only. No real generation or balance changes.</span></p>'''))
parts.append(section('surfaces','Impact across the app',table(['Surface','Product change','Implementation area'],p['impacts'])))
parts.append(section('states','State and recovery model',table(['State','Meaning','Safe actions','Credit treatment'],p['states'])))
parts.append(section('edges','Known edge cases and failure states',para('This is the initial coverage inventory, not a claim that every possible failure has already been discovered. Each feature must extend it when QA finds a new case.')+table(['Case','Feature','Trigger','Learner-facing state / copy','Required behavior'],p['edges'])))
feature_html=''
for f in p['features']:
    feature_html+=f'<article class="feature" id="{f["id"]}"><div class="feature-head"><span class="id">{f["id"]}</span><span class="tag">{e(f["status"])}</span></div><h3>{e(f["title"])}</h3>{para(f["outcome"])}<dl>'
    for label,value in [('Scope',f['scope']),('App and code areas',f['files']),('Dependencies',', '.join(f['depends']) or 'Product/experience contract'),('Existing workstreams',', '.join(f['or'])),('Feature QA',f['qa']),('Exit check',f['exit'])]:
        feature_html+='<dt>'+e(label)+'</dt><dd>'+e(value)+'</dd>'
    feature_html+='</dl></article>'
parts.append(section('features','3. Build and QA one feature at a time',para('F-01 → F-02 → F-03 → F-04 → F-05 → F-06 → F-07 → F-08 → F-09. F-10 is optional tutor scope and becomes a dependency of F-09 if selected. All feature implementation and QA below are planned; prior adapter/database evidence is called out separately.')+feature_html))
parts.append(section('qa','The delivery loop and release gate',table(['Gate','Required work'],p['qa'])+para('A feature is not “done” because its code exists. Record local QA, required live checks and hosted acceptance separately. A staging pass does not authorize a production release.')))
parts.append(section('metrics','How we will judge the result',table(['Measure','Proposed acceptance target'],p['metrics'])))
parts.append(section('gaps','Changes the existing technical plan needs',table(['Gap','Required change'],p['technicalGaps'])))
parts.append(section('decisions','Decisions and assumptions',table(['ID','Topic','Recommendation / status','When it matters'],p['decisions'])))
parts.append(section('evidence','Evidence and current limits',para('This delivery plan is based on source and continuity inspection. It does not add live model, accounting, customer-research or release evidence. Prototype verification: all 22 states rendered; 21 interaction checks passed in the local in-app browser. Desktop and narrow mobile layouts were inspected. These checks do not validate the real product, a wallet, live models or hosted recovery. Product-feature QA remains unrun.')+table(['Reference','Source'],p['sources'])+'''<p><a href="verification.json">Prototype verification record</a> · <a href="https://app.notion.com/p/3f471b32838481e59768fdedcd9a615b">PRD and feature tracker in Notion</a> · <a href="https://github.com/productdave/learnable-learn-anything/pull/4">Existing draft PR #4</a> · <a href="https://app.notion.com/p/3f471b32838481cb8c69fd30cafd18a7">Canonical roadmap</a></p>'''))
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:85px}body{margin:0;background:#f4f6f1;color:#25392f;font:17px/1.65 system-ui,-apple-system,sans-serif}a{color:#195e47;text-underline-offset:3px}a:focus-visible,button:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:3px solid #cd840a;outline-offset:4px}header,main,footer{max-width:1180px;margin:auto;padding:32px 26px}header{padding-top:54px}h1,h2,h3{line-height:1.2}h1{font:600 clamp(2.3rem,5vw,3.9rem)/1.1 Georgia,serif;margin:14px 0 20px;max-width:900px}h2{font:600 2rem/1.2 Georgia,serif;margin:0 0 22px}h3{font-size:1.15rem;margin:22px 0 10px}p{max-width:95ch}small,.muted{color:#52665a}.eyebrow,.id{font-size:.82rem;letter-spacing:.06em;text-transform:uppercase}.lead{font-size:1.24rem}.callout{padding:22px 26px;background:#e5efe5;border-left:5px solid #38765c;border-radius:5px;margin:24px 0}.callout h3{margin-top:0}.status{font-size:.94rem}.button{display:inline-block;background:#245b45;color:white;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:650;margin:8px 10px 8px 0;min-height:44px}nav{position:sticky;top:0;z-index:2;background:#fffef9ed;border-block:1px solid #d7ded5;display:flex;gap:22px;overflow:auto;padding:17px max(26px,calc((100vw - 1128px)/2))}nav a{font-size:.9rem;white-space:nowrap}section{background:#fff;border:1px solid #dce2d8;border-radius:12px;margin:0 0 28px;padding:30px}article+article{border-top:1px solid #e3e7df;padding-top:8px}.flow{display:flex;list-style:none;padding:0;gap:10px;flex-wrap:wrap}.flow li{flex:1;min-width:145px;background:white;border:1px solid #d5ddd1;padding:14px 16px;border-radius:8px;font-size:.91rem}.flow span{display:block;color:#5b6a60;font-size:.8rem}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.91rem}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dce3d9;padding:13px 12px;min-width:140px}th{background:#edf2e9;font-size:.8rem;letter-spacing:.015em}td:first-child{font-weight:600;min-width:100px}tr:last-child td{border:0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.cards article{border:0}.feature{padding:24px 0}.feature h3{font-size:1.4rem}.feature-head{display:flex;gap:15px;align-items:center}.tag{font-size:.78rem;border:1px solid #d3dccf;border-radius:20px;padding:3px 10px;color:#4e6455}dl{display:grid;grid-template-columns:170px 1fr;gap:10px 22px;font-size:.95rem}dt{font-weight:650}dd{margin:0}footer{font-size:.85rem;color:#58695f;padding-top:0}@media(max-width:700px){header,main,footer{padding:24px 16px}section{padding:22px 18px}nav{padding:14px 16px;gap:18px}.cards{display:block}dl{display:block}dt{margin-top:14px}h2{font-size:1.65rem}.feature-head{align-items:flex-start}.flow li{min-width:125px}td,th{min-width:150px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{nav,.button{display:none}body{background:white;font-size:11pt}header,main{padding:12px 0}section{border:0;padding:16px 0}.table-wrap{overflow:visible}table{font-size:9pt}th,td{min-width:0}h2,h3{break-after:avoid}tr{break-inside:avoid}header{break-after:page}.feature{break-inside:avoid}}'''
head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(p['title'])} — product delivery plan</title><style>{css}</style></head><body><header><div class="eyebrow">Learnable · {e(p['version'])}</div><h1>{e(p['title'])}</h1><p class="lead">{e(p['summary'])}</p><div class="callout"><h3>Where we're at</h3><p class="status">{e(p['status'])}</p><h3>What's next</h3><p>{e(p['next'])}</p><p><strong>Scope assumption:</strong> {e(p['decision'])}</p></div><ol class="flow"><li>1 · Product definition<span>Outcome, scope and rules</span></li><li>2 · Experience design<span>Journey, states and surfaces</span></li><li>3 · One feature<span>A usable, bounded slice</span></li><li>4 · Feature QA<span>Fix and record evidence</span></li><li>5 · Release later<span>Integrated acceptance first</span></li></ol><a class="button" href="prototype.html">Try the experience prototype</a><a href="#features">See the feature sequence</a></header><nav aria-label="Delivery plan sections"><a href="#definition">PRD</a><a href="#credits">Credits</a><a href="#journey">Journey</a><a href="#surfaces">App impact</a><a href="#edges">Edge cases</a><a href="#features">Features</a><a href="#qa">QA &amp; release</a><a href="#decisions">Decisions</a></nav><main>'''
(root/'index.html').write_text(head+''.join(parts)+'</main><footer>Draft product contract and design proposal. Prototype numbers are examples. The existing technical foundation remains in draft PR #4; no production release is implied.</footer></body></html>')
print('Rendered delivery plan:',root/'index.html')
